INSERT INTO "comments" ("id","slug","name","message","created_at","likes","reply","reply_updated_at","reply_likes","edited_at","edit_token_hash","is_owner") VALUES(7,'east-africa-safari','Vivian','謝謝Herry為旅行心得用文字表達出來留下美好的回憶。太棒了👏','2026-09-20 23:29:11',2,'謝謝 Vivian的留言。這真是一個很棒的旅程。','2026-09-21 10:59:02',1,NULL,NULL,0);
