INSERT INTO "comments" ("id","slug","name","message","created_at","likes","reply","reply_updated_at","reply_likes","edited_at","edit_token_hash","is_owner") VALUES(9,'taiwan-travelogue','Maggie',replace('盡管楊双子文字柔美，但個人總覺得讀起來過於「日式輕小說」。後來了解其作品多以百合情感為核心，讓我隱約覺得有些迎合當代大眾喜好的意味。\n《臺灣漫遊錄》之所以成功，我認為很大一部分來自其巧妙的「包裝」，將一部虛構小說以近乎真實史料的方式呈現，模糊虛構與現實之間的界線，也確實構成了這本書最特殊的魅力。然而，若撇除這層形式上的巧思，單就作品本身而言，個人仍覺得或許有些過譽了。','\n',char(10)),'2026-09-21 01:34:53',1,replace('謝謝你的留言。👍\n也有人和妳的看法類似。覺得這種包裝改變了一般讀者與作者對前後文框架的認知。','\n',char(10)),'2026-09-22 00:26:46',0,NULL,NULL,0);
INSERT INTO "comments" ("id","slug","name","message","created_at","likes","reply","reply_updated_at","reply_likes","edited_at","edit_token_hash","is_owner") VALUES(10,'east-africa-safari','秀淇','太幸運有哥和我們同團丶幫著大家寫下這些令人美好的回憶丶生動又精采的文筆真棒','2026-09-21 07:49:55',2,'謝謝你這麼說喔。你喜歡我也很高興。','2026-09-21 10:58:37',0,NULL,NULL,0);
