INSERT INTO "comments" ("id","slug","name","message","created_at","likes","reply","reply_updated_at","reply_likes","edited_at","edit_token_hash","is_owner") VALUES(12,'east-africa-safari','Amy','Henry, 東非遊記實在太精彩了。旅遊最棒的事情就是把它記錄下來，可以慢慢回味當時所有的珍貴回憶！','2026-09-22 02:18:37',1,'謝謝妳看到。我有用心寫喔 ☺️','2026-09-24 05:20:05',0,NULL,NULL,0);
