INSERT INTO "comments" ("id","slug","name","message","created_at","likes","reply","reply_updated_at","reply_likes","edited_at","edit_token_hash","is_owner") VALUES(14,'culture-to-developmnt','SHAO-YUN',replace('上星期才去快閃了一下首爾，算是第一次去吧。\n本來還是抱著"是不是韓國人比較粗魯或是比較浮誇"，但是看到的是已經對自己國家文化自信的從容的韓國人，整個欣欣向榮蓬勃的感覺 (也有可能是假日吧)。\n用著S牌手機與電視，看著 Netflix的滑不完的韓劇，Youtube裡烏克蘭年輕妹妹團體跳著《BAD》帥到爆炸的震胸舞，似乎無孔不入地滲透了日常...','\n',char(10)),'2026-09-22 07:44:50',0,'我還沒去過韓國呢😯','2026-09-23 14:55:48',0,NULL,NULL,0);
