INSERT INTO "comments" ("id","slug","name","message","created_at","likes","reply","reply_updated_at","reply_likes","edited_at","edit_token_hash","is_owner") VALUES(17,'east-africa-safari','多明哥','人與野生動物共享著這片土地的寂靜與狂野，堪稱一場洗滌心靈的終極冒險。','2026-09-24 05:16:12',1,'謝謝你。其實我不太確定動物是否願意和我們共享。例如那隻獅子的表情似乎無所謂，又有點無奈。','2026-09-24 13:03:08',1,NULL,NULL,0);
