INSERT INTO "comments" ("id","slug","name","message","created_at","likes","reply","reply_updated_at","reply_likes","edited_at","edit_token_hash","is_owner") VALUES(19,'east-africa-safari','Jennifer',replace('謝謝您的旅遊分享，好精彩! 特別是遠在天邊，近在眼前的獅子🦁\n在現代化和文明的不斷推進，我們似乎失去對大自然的連結和敬畏。透由您的野性之旅，那股最初的純粹也被喚醒了。😄\n希望未來也能身歷其😜','\n',char(10)),'2026-09-28 03:26:42',1,replace('謝謝妳的留言。\n趕快去吧。肯亞不但動物可愛，男士也是很帥的喲。','\n',char(10)),'2026-09-28 08:25:31',1,NULL,NULL,0);
INSERT INTO "comments" ("id","slug","name","message","created_at","likes","reply","reply_updated_at","reply_likes","edited_at","edit_token_hash","is_owner") VALUES(20,'east-africa-safari','Evelyn','很棒，很有內容值得一再觀賞和拜讀','2026-09-29 13:32:38',1,replace('謝謝妳的留言。\n肯亞的動物比我們在那米比亞時多一些，也近一些。','\n',char(10)),'2026-09-30 10:28:11',0,NULL,NULL,0);
INSERT INTO "comments" ("id","slug","name","message","created_at","likes","reply","reply_updated_at","reply_likes","edited_at","edit_token_hash","is_owner") VALUES(21,'east-africa-safari','SY','你用「遊獵」是比網路給的翻譯「獵遊」感覺上稍微文明一點。但是時至今日，Safari的活動中「獵」的成分應該非常低了！當然獵這個字不一定是打獵，只是會引起聯想。有什麼更好的翻譯呢？','2026-10-01 00:08:58',1,replace('我不取「獵遊」而說「遊獵」，單純是後者順口好聽。\n現今自然已無人用獵槍射擊動物，而是以鏡頭拍攝動物。二者都是shoot，只是「獵」的工具不同罷了。','\n',char(10)),'2026-10-01 12:57:50',1,NULL,NULL,0);
