PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE comments (   id INTEGER PRIMARY KEY AUTOINCREMENT,   slug TEXT NOT NULL,   name TEXT NOT NULL,   message TEXT NOT NULL,   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   likes INTEGER NOT NULL DEFAULT 0,   reply TEXT,   reply_updated_at TEXT , reply_likes INTEGER NOT NULL DEFAULT 0, edited_at TEXT, edit_token_hash TEXT, is_owner INTEGER NOT NULL DEFAULT 0);
CREATE TABLE comment_replies (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT NOT NULL,
  comment_id INTEGER NOT NULL,
  target_type TEXT NOT NULL CHECK (target_type IN ('comment', 'legacy', 'reply')),
  target_id INTEGER NOT NULL,
  name TEXT NOT NULL,
  message TEXT NOT NULL,
  is_owner INTEGER NOT NULL DEFAULT 0,
  likes INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (comment_id) REFERENCES comments(id)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_comment_replies_slug_comment
  ON comment_replies(slug, comment_id, created_at, id);
